INSERT INTO public.news (id, title, slug, excerpt, content, image, category, author_id, published, published_at, created_at, updated_at) VALUES ('183f094d-b254-4b37-b027-761171f16c2e', 'Lancement de la saison 2026-2027', 'lancement-de-la-saison-2026-2027', 'Le calendrier départemental est en ligne', 'La saison 2026-2027 du championnat des Deux-Sèvres démarre avec 26 clubs inscrits en D1, D2 et D3. Retrouvez le calendrier complet et les classements en temps réel sur la plateforme.', NULL, 'championnat', 'f363e6da-b867-4d0d-9e5f-96f60b3be5b9', true, '2026-11-10 09:00:00+00', '2026-11-08 10:00:00+00', '2026-11-08 10:00:00+00');
INSERT INTO public.news (id, title, slug, excerpt, content, image, category, author_id, published, published_at, created_at, updated_at) VALUES ('409abb06-8f93-43e2-94c5-4434c1265fa7', 'Coupe des Clubs 79 : inscriptions ouvertes', 'coupe-des-clubs-79-inscriptions-ouvertes', '16 équipes max, finale à 15 points', 'La Coupe des Clubs 79 ouvre ses inscriptions jusqu''au 1er décembre. Finale en 15 points comme le veut le règlement.', NULL, 'coupe', 'f363e6da-b867-4d0d-9e5f-96f60b3be5b9', true, '2026-11-12 14:30:00+00', '2026-11-08 10:00:00+00', '2026-11-08 10:00:00+00');
INSERT INTO public.news (id, title, slug, excerpt, content, image, category, author_id, published, published_at, created_at, updated_at) VALUES ('35a35d20-a616-41dc-b3ec-0b8b213d71f0', 'Open de Challans : 32 équipes en lice', 'open-de-challans-32-equipes-en-lice', 'Rendez-vous le 12 décembre à la salle des fêtes', 'L''open annuel de Challans réunira 32 doublettes en fonte. Inscriptions sur la page du tournoi.', NULL, 'tournoi', 'f363e6da-b867-4d0d-9e5f-96f60b3be5b9', true, '2026-11-14 18:00:00+00', '2026-11-08 10:00:00+00', '2026-11-08 10:00:00+00');
INSERT INTO public.news (id, title, slug, excerpt, content, image, category, author_id, published, published_at, created_at, updated_at) VALUES ('f2f87cbf-c27f-4373-918e-fc1b9f6c31dd', 'Rappel : victoire à 13 points, 15 en finale', 'rappel-victoire-a-13-points-15-en-finale', 'Le règlement officiel FNSMR s''applique', 'Rappel du règlement : une partie se joue en 13 points, 15 points en finale (la balle). Aucun match nul possible au-delà de la limite de manches.', NULL, 'reglement', 'f363e6da-b867-4d0d-9e5f-96f60b3be5b9', true, '2026-11-08 11:00:00+00', '2026-11-08 10:00:00+00', '2026-11-08 10:00:00+00');
